COULEURS = ["Beige", "Blanc", "Bleu", "Bordeaux", "Camel", "Chocolat", "Écru", "Gris", "Kaki",
            "Marine", "Noir", "Rose", "Rouge", "Taupe", "Terracotta", "Vert"]


def creer_couleurs_et_modeles(apps, schema_editor):
    Couleur = apps.get_model("stock", "Couleur")
    for nom in COULEURS:
        Couleur.objects.get_or_create(nom=nom)
    # Chaque article existant devient un modèle à taille unique, sans couleur.
    Modele = apps.get_model("stock", "Modele")
    Reference = apps.get_model("stock", "Reference")
    for ref in Reference.objects.all():
        modele = Modele.objects.create(
            nom=ref.designation, categorie_id=ref.categorie_id, cout_achat=ref.cout_achat,
            prix_vente=ref.prix_vente, active=ref.active,
        )
        ref.modele_id, ref.taille, ref.sku = modele.pk, "TU", f"MA{modele.pk:04d}-TU-U"
        ref.save(update_fields=["modele", "taille", "sku"])


